def find_similar_sets(test_cases):
    results = []
    for case in test_cases:
        n, sets = case
        similar_found = False
        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i].intersection(sets[j])) >= 2:
                    results.append((i + 1, j + 1))
                    similar_found = True
                    break
            if similar_found:
                break
        if not similar_found:
            results.append(-1)
    return results

